package com.alsafa.native4.core;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;/** Additive watch attributes for advisor/catalog; never rebuilds products. */final class CoreSchemaV20{static void create(SQLiteDatabase db){add(db,"products","gender","TEXT NOT NULL DEFAULT ''");add(db,"products","display_type","TEXT NOT NULL DEFAULT ''");add(db,"products","dial_color","TEXT NOT NULL DEFAULT ''");add(db,"products","strap_type","TEXT NOT NULL DEFAULT ''");add(db,"products","case_color","TEXT NOT NULL DEFAULT ''");}private static void add(SQLiteDatabase db,String table,String col,String def){try(Cursor c=db.rawQuery("PRAGMA table_info("+table+")",null)){while(c.moveToNext())if(col.equals(c.getString(c.getColumnIndexOrThrow("name"))))return;}db.execSQL("ALTER TABLE "+table+" ADD COLUMN "+col+" "+def);}}